<?php
namespace Tests\Feature;
use App\Application\Documentos\{AprobarVersionDocumento,RechazarVersionDocumento,SometerVersionDocumento}; use App\Application\Contexto\ContextResolver; use App\Models\{Copropiedad,Documento,DocumentoVersion,Organizacion,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Validation\ValidationException; use Tests\Concerns\CreatesInstitutionalContext; use Tests\TestCase;
class DocumentoVersionWorkflowTest extends TestCase { use CreatesInstitutionalContext,RefreshDatabase;
 public function test_draft_pending_approved_and_rejected_transitions_record_one_activity_each():void{[$o,$c]=$this->createInstitutionalContext();$u=User::factory()->create();$this->createContextualIdentity($u,$o,$c,'admin',['documentos.gestionar','documentos.aprobar']);$ctx=app(ContextResolver::class)->resolverExplicito($o->id,$c->id,$u->id);$d=$this->doc($o,$c,$u);$v=$this->ver($d,1);app(SometerVersionDocumento::class)->ejecutar($ctx,$u,$d,$v);app(AprobarVersionDocumento::class)->ejecutar($ctx,$u,$d,$v,now()->toDateString());$r=$this->ver($d,2);app(SometerVersionDocumento::class)->ejecutar($ctx,$u,$d,$r);app(RechazarVersionDocumento::class)->ejecutar($ctx,$u,$d,$r,'Debe corregir el contenido.');$this->assertSame('aprobada',$v->fresh()->estado->value);$this->assertSame('rechazada',$r->fresh()->estado->value);$this->assertDatabaseCount('documento_actuaciones',4);}
 public function test_single_pending_and_rejection_observation_are_enforced():void{[$o,$c]=$this->createInstitutionalContext();$u=User::factory()->create();$this->createContextualIdentity($u,$o,$c,'admin',['documentos.gestionar','documentos.aprobar']);$ctx=app(ContextResolver::class)->resolverExplicito($o->id,$c->id,$u->id);$d=$this->doc($o,$c,$u);$a=$this->ver($d,1);$b=$this->ver($d,2);app(SometerVersionDocumento::class)->ejecutar($ctx,$u,$d,$a);try{app(SometerVersionDocumento::class)->ejecutar($ctx,$u,$d,$b);$this->fail();}catch(ValidationException){$this->assertTrue(true);}try{app(RechazarVersionDocumento::class)->ejecutar($ctx,$u,$d,$a,'');$this->fail();}catch(ValidationException){$this->assertTrue(true);}}
 private function doc(Organizacion $o,Copropiedad $c,User $u):Documento{$d=new Documento(['ambito'=>'copropiedad','propietario_documental_user_id'=>$u->id,'tipo'=>'documento_general','categoria'=>'administrativo','titulo'=>'D','nivel_acceso'=>'interno','estado'=>'activo']);$d->forceFill(['organizacion_id'=>$o->id,'copropiedad_id'=>$c->id])->save();return $d;}
 private function ver(Documento $d,int $n):DocumentoVersion{$v=new DocumentoVersion(['numero'=>$n,'estado'=>'borrador','origen'=>'usuario','nombre_original'=>"$n.pdf",'ruta_archivo'=>"$n.pdf",'mime_type'=>'application/pdf','extension'=>'pdf','tamano_bytes'=>1,'hash_sha256'=>hash('sha256',"$n-{$d->id}")]);$v->forceFill(['documento_id'=>$d->id,'organizacion_id'=>$d->organizacion_id,'copropiedad_id'=>$d->copropiedad_id])->save();return $v;}}
